18	#[derive(Subcommand)]
19	enum Commands {
20	    /// Install Claude Code hooks
21	    Init {
22	        /// Install globally (~/.claude/settings.json)
23	        #[arg(short, long)]
24	        global: bool,
25	    },
26	    /// Remove Claude Code hooks
27	    Uninit {
28	        /// Remove from global settings
29	        #[arg(short, long)]
30	        global: bool,
31	    },
32	    /// Wrap and compress a command's output
33	    Wrap {
34	        /// Command and arguments to execute
35	        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
36	        command: Vec<String>,
37	    },
38	    /// Show local savings statistics
39	    Stats {
40	        /// Output as JSON
41	        #[arg(long)]
42	        json: bool,
43	        /// Number of days to include (default: 90)
44	        #[arg(long)]
45	        days: Option<i64>,
46	        /// Show waste pattern analysis
47	        #[arg(long)]
48	        waste: bool,
49	    },
50	    /// Sync local events to cloud
51	    Sync {
52	        /// Sync once and exit (default: continuous daemon)
53	        #[arg(long)]
54	        once: bool,
55	        /// API URL override
56	        #[arg(long, env = "CODEFLOW_API_URL")]
57	        api_url: Option<String>,
58	    },
59	    /// Authenticate with CODEFLOW cloud
60	    Login {
61	        /// Auth server URL override
62	        #[arg(long, env = "CODEFLOW_AUTH_URL")]
63	        auth_url: Option<String>,
64	    },
65	    /// Show authentication status
66	    Status,
67	    /// Remove stored credentials
68	    Logout,
69	    /// Dry-run model routing classification
70	    Route {
71	        /// Command to classify (quoted string)
72	        command: String,
73	        /// Simulated context token count
74	        #[arg(long, default_value = "5000")]
75	        tokens: u64,
76	        /// File paths involved (comma-separated)
77	        #[arg(long, value_delimiter = ',')]
78	        files: Vec<String>,
79	    },
80	    /// Manage the dedup cache
81	    Cache {
82	        #[command(subcommand)]
83	        action: CacheAction,
84	    },
