155	fn handle_route(command: &str, tokens: u64, files: &[String]) -> anyhow::Result<()> {
156	    let cmd = command.to_string();
157	    if cmd.is_empty() {
158	        anyhow::bail!("no command provided");
159	    }
160	
161	    let file_refs: Vec<&str> = files.iter().map(|f| f.as_str()).collect();
162	    let extensions = codeflow_core::router::extensions_from_paths(&file_refs);
163	
164	    let input = codeflow_core::router::RoutingInput {
165	        command: cmd.clone(),
166	        context_tokens: tokens,
167	        file_extensions: extensions,
168	        session_event_count: 0,
169	    };
170	
171	    let decision = codeflow_core::router::classify(&input);
172	
173	    println!("Command:    {}", cmd);
174	    println!("Tokens:     {}", tokens);
175	    println!("Score:      {:.2}", decision.score);
176	    println!("Complexity: {:?}", decision.complexity);
177	    println!("Route to:   {} ({})", decision.tier.name(), format!("${}/1M tokens", decision.tier.cost_per_million_tokens()));
178	    println!("Savings:    {:.0}% vs Opus", decision.estimated_savings_pct);
179	    if !decision.reason.is_empty() {
180	        println!("Reason:     {}", decision.reason);
181	    }
182	
183	    Ok(())
184	}
