186	fn handle_cache(action: CacheAction) -> anyhow::Result<()> {
187	    let db_path = paths::db_path();
188	    match action {
189	        CacheAction::Clear => {
190	            if db_path.exists() {
191	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
192	                let removed = cache.clear()?;
193	                println!("Cleared {} cache entries.", removed);
194	            } else {
195	                println!("Cache is empty.");
196	            }
197	            Ok(())
198	        }
199	        CacheAction::Info => {
200	            if db_path.exists() {
201	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
202	                let count = cache.entry_count()?;
203	                println!("Cache entries: {}", count);
204	                println!("Database: {}", db_path.display());
205	            } else {
206	                println!("No cache database found.");
207	            }
208	            Ok(())
209	        }
210	    }
211	}
