373	fn handle_post_tool_use() -> anyhow::Result<()> {
374	    let input = match read_stdin() {
375	        Ok(s) => s,
376	        Err(_) => {
377	            println!("{{}}");
378	            return Ok(());
379	        }
380	    };
381	
382	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
383	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
384	    let tool_result = parsed
385	        .get("tool_result")
386	        .and_then(|v| v.as_str())
387	        .unwrap_or("");
388	
389	    if let Some(tn) = tool_name {
390	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
391	            let file_path = parsed
392	                .get("tool_input")
393	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
394	
395	            if let Some(row_id) = read_last_pre_id(tn, file_path.as_deref()) {
396	                let session_id = session_id();
397	                if let Ok(session_log) = open_session_log(&session_id) {
398	                    let capped = if tool_result.len() > 1_048_576 {
399	                        &tool_result[..1_048_576]
400	                    } else {
401	                        tool_result
402	                    };
403	                    let content_hash =
404	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
405	                    let token_count = (tool_result.len() as i64 + 3) / 4;
406	
407	                    let mtime_ns =
408	                        file_path.as_deref().and_then(|fp| get_file_mtime_ns(fp));
409	
410	                    let _ = session_log.record_post(
411	                        row_id,
412	                        &content_hash,
413	                        token_count,
414	                        mtime_ns,
415	                    );
416	                }
417	            }
418	        }
419	    }
420	
421	    println!("{{}}");
422	    Ok(())
423	}
