434	fn last_pre_id_path(tool_name: &str, file_path: Option<&str>) -> std::path::PathBuf {
435	    let key = format!(
436	        "{}:{}",
437	        tool_name,
438	        file_path.unwrap_or("_")
439	    );
440	    let hash = blake3::hash(key.as_bytes()).to_hex();
441	    paths::data_dir().join(format!("pre_id_{}", &hash[..16]))
442	}
443	
444	fn write_last_pre_id(tool_name: &str, file_path: Option<&str>, row_id: i64) {
445	    let _ = std::fs::create_dir_all(paths::data_dir());
446	    let _ = std::fs::write(last_pre_id_path(tool_name, file_path), row_id.to_string());
447	}
448	
449	fn read_last_pre_id(tool_name: &str, file_path: Option<&str>) -> Option<i64> {
450	    let path = last_pre_id_path(tool_name, file_path);
451	    let id = std::fs::read_to_string(&path).ok()?.trim().parse().ok();
452	    let _ = std::fs::remove_file(&path);
453	    id
454	}
455	
456	fn get_file_mtime_ns(path: &str) -> Option<i64> {
457	    let meta = std::fs::metadata(path).ok()?;
458	    let modified = meta.modified().ok()?;
459	    let duration = modified
460	        .duration_since(std::time::UNIX_EPOCH)
461	        .ok()?;
462	    Some(duration.as_nanos() as i64)
463	}
