465	fn should_wrap(command: &str) -> bool {
466	    let first_word = command.split_whitespace().next().unwrap_or("");
467	    let stem = std::path::Path::new(first_word)
468	        .file_stem()
469	        .and_then(|s| s.to_str())
470	        .unwrap_or(first_word);
471	    let wrappable = [
472	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
473	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
474	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
475	    ];
476	    wrappable.contains(&stem)
477	}
