479	fn shell_quote(s: &str) -> String {
480	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
481	        format!("'{}'", s.replace('\'', "'\\''"))
482	    } else {
483	        s.to_string()
484	    }
485	}
