13	pub fn execute(command_args: &[String]) -> Result<()> {
14	    if command_args.is_empty() {
15	        anyhow::bail!("No command specified");
16	    }
17	
18	    let program = &command_args[0];
19	    let args = &command_args[1..];
20	
21	    let start = Instant::now();
22	    let cmd_output = run_command(program, args)?;
23	    let raw_output = &cmd_output.combined;
24	    let session_id = session_id();
25	    let project_dir = std::env::current_dir()
26	        .unwrap_or_default()
27	        .to_string_lossy()
28	        .to_string();
29	
30	    let result = match compress(raw_output, program, args, &session_id, &project_dir) {
31	        Ok(r) => r,
32	        Err(e) => {
33	            tracing::warn!("compression failed, passing through: {}", e);
34	            print_output(raw_output);
35	            propagate_exit(cmd_output.exit_code);
36	            return Ok(());
37	        }
38	    };
39	
40	    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
41	    tracing::debug!(
42	        command = program,
43	        input_len = result.filter.input_len,
44	        output_len = result.filter.output_len,
45	        dedup_hit = result.dedup_hit,
46	        latency_ms = latency_ms,
47	        "wrap complete"
48	    );
49	
50	    if result.dedup_hit {
51	        if let Some(summary) = &result.dedup_summary {
52	            print_output(summary);
53	        } else {
54	            print_output(&result.filter.output);
55	        }
56	    } else {
57	        print_output(&result.filter.output);
58	    }
59	
60	    propagate_exit(cmd_output.exit_code);
61	    Ok(())
62	}
63	
64	struct WrapResult {
65	    filter: FilterResult,
66	    dedup_hit: bool,
67	    dedup_summary: Option<String>,
68	}
69	
70	fn compress(
71	    raw_output: &str,
72	    program: &str,
73	    args: &[String],
74	    session_id: &str,
75	    project_dir: &str,
76	) -> Result<WrapResult> {
77	    let data_dir = paths::data_dir();
78	    std::fs::create_dir_all(&data_dir)?;
79	    let db_path = paths::db_path();
80	
81	    let filters_dir = paths::filters_dir();
82	    let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap_or_else(|_| FilterPipeline::new());
83	
84	    let filter_result = pipeline.apply(program, &args.iter().map(|s| s.to_string()).collect::<Vec<_>>(), raw_output);
85	
86	    let dedup_cache = DedupCache::open(&db_path, session_id)?;
87	    let content_to_check = &filter_result.output;
88	    let fake_mtime = file_content_mtime(content_to_check);
89	    let dedup_result = dedup_cache.lookup(
90	        &format!("cmd:{}:{}", program, args.join(" ")),
91	        fake_mtime,
92	        content_to_check,
93	    )?;
94	
95	    let tokens_saved_compress = if filter_result.filter_applied {
96	        estimate_tokens(filter_result.input_len) - estimate_tokens(filter_result.output_len)
97	    } else {
98	        0
99	    };
100	
101	    let tracking = TrackingDb::open(&db_path)?;
102	
103	    if filter_result.filter_applied && tokens_saved_compress > 0 {
104	        tracking.record(&TrackingEvent {
105	            command: program.to_string(),
106	            input_tokens: estimate_tokens(filter_result.input_len) as u64,
107	            output_tokens: estimate_tokens(filter_result.output_len) as u64,
108	            tokens_saved: tokens_saved_compress as u64,
109	            layer: SavingsLayer::Compression,
110	            project: project_dir.to_string(),
111	            session_id: session_id.to_string(),
112	        })?;
113	    }
114	
115	    if dedup_result.cache_hit {
116	        tracking.record(&TrackingEvent {
117	            command: program.to_string(),
118	            input_tokens: estimate_tokens(filter_result.output_len) as u64,
119	            output_tokens: 0,
120	            tokens_saved: dedup_result.tokens_saved,
121	            layer: SavingsLayer::Dedup,
122	            project: project_dir.to_string(),
123	            session_id: session_id.to_string(),
124	        })?;
125	    }
126	
127	    if let Ok(event_buf) = EventBuffer::open(&db_path) {
128	        let event = proto::Event {
129	            id: uuid::Uuid::new_v4().to_string(),
130	            timestamp_ms: chrono::Utc::now().timestamp_millis(),
131	            session_id: session_id.to_string(),
132	            project_dir: project_dir.to_string(),
133	            command: format!("{} {}", program, args.join(" ")),
134	            event_type: if dedup_result.cache_hit {
135	                proto::EventType::Dedup as i32
136	            } else {
137	                proto::EventType::Compression as i32
138	            },
139	            compression: Some(proto::CompressionEvent {
140	                input_bytes: filter_result.input_len as u64,
141	                output_bytes: filter_result.output_len as u64,
142	                input_tokens: estimate_tokens(filter_result.input_len) as u64,
143	                output_tokens: estimate_tokens(filter_result.output_len) as u64,
144	                tokens_saved: tokens_saved_compress as u64,
145	                filter_name: program.to_string(),
146	                compression_level: "default".to_string(),
147	                latency_ms: 0.0,
148	            }),
149	            dedup: if dedup_result.cache_hit {
150	                Some(proto::DedupEvent {
151	                    content_hash: dedup_result.content_hash.clone(),
152	                    cache_hit: true,
153	                    tokens_saved: dedup_result.tokens_saved,
154	                    file_path: String::new(),
155	                    latency_ms: 0.0,
156	                })
157	            } else {
158	                None
159	            },
160	        };
161	        let _ = event_buf.append(&event);
162	    }
163	
164	    Ok(WrapResult {
165	        filter: filter_result,
166	        dedup_hit: dedup_result.cache_hit,
167	        dedup_summary: dedup_result.summary,
168	    })
169	}
170	
171	struct CommandOutput {
172	    combined: String,
173	    exit_code: Option<i32>,
174	}
175	
176	fn run_command(program: &str, args: &[String]) -> Result<CommandOutput> {
177	    let output = Command::new(program)
178	        .args(args)
179	        .output()
180	        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;
181	
182	    let mut combined = String::new();
183	    if !output.stdout.is_empty() {
184	        combined.push_str(&String::from_utf8_lossy(&output.stdout));
185	    }
186	    if !output.stderr.is_empty() {
187	        if !combined.is_empty() {
188	            combined.push('\n');
189	        }
190	        combined.push_str(&String::from_utf8_lossy(&output.stderr));
191	    }
192	    Ok(CommandOutput {
193	        combined,
194	        exit_code: output.status.code(),
195	    })
196	}
197	
198	fn print_output(text: &str) {
199	    let stdout = std::io::stdout();
200	    let mut handle = stdout.lock();
201	    let _ = handle.write_all(text.as_bytes());
202	    if !text.ends_with('\n') {
203	        let _ = handle.write_all(b"\n");
204	    }
205	    let _ = handle.flush();
206	}
207	
208	fn propagate_exit(exit_code: Option<i32>) {
209	    if let Some(code) = exit_code {
210	        if code != 0 {
211	            std::process::exit(code);
212	        }
213	    }
214	}
215	
216	fn estimate_tokens(byte_len: usize) -> usize {
217	    (byte_len + 3) / 4
218	}
219	
220	fn file_content_mtime(content: &str) -> u64 {
221	    let hash = blake3::hash(content.as_bytes());
222	    let bytes = hash.as_bytes();
223	    u64::from_le_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
224	}
225	
226	fn session_id() -> String {
227	    std::env::var("CLAUDE_SESSION_ID")
228	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
229	        .unwrap_or_else(|_| {
230	            // Use parent PID for stable session within one Claude Code run
231	            #[cfg(unix)]
232	            let ppid = unsafe { libc::getppid() } as u32;
233	            #[cfg(not(unix))]
234	            let ppid = std::process::id();
235	            format!("local-{}", ppid)
236	        })
237	}
