243	            ReadDedupResult::Hit {
244	                tokens_saved,
245	                context_message,
246	            } => {
247	                assert_eq!(tokens_saved, 30);
248	                assert!(context_message.contains("Glob"));
249	            }
250	            ReadDedupResult::Miss => panic!("expected Hit"),
251	        }
252	    }
