19	pub fn login(api_url: Option<&str>) -> Result<()> {
20	    let env_url = std::env::var("CODEFLOW_AUTH_URL").ok();
21	    let auth_url = api_url
22	        .or(env_url.as_deref())
23	        .unwrap_or(DEFAULT_AUTH_URL);
24	
25	    let listener = TcpListener::bind("127.0.0.1:0")?;
26	    let port = listener.local_addr()?.port();
27	    let redirect_uri = format!("http://localhost:{}/callback", port);
28	
29	    let authorize_url = format!(
30	        "{}/authorize?redirect_uri={}&response_type=code&client_id=codeflow-cli",
31	        auth_url,
32	        urlencoding::encode(&redirect_uri)
33	    );
34	
35	    println!("Opening browser for authentication...");
36	    println!("If browser doesn't open, visit: {}", authorize_url);
37	    let _ = open::that(&authorize_url);
38	
39	    println!("Waiting for authentication callback on port {}...", port);
40	
41	    let (stream, _) = listener.accept()?;
42	    let mut reader = BufReader::new(&stream);
43	    let mut request_line = String::new();
44	    reader.read_line(&mut request_line)?;
45	
46	    let code = extract_code(&request_line);
47	
48	    let response_body = if code.is_some() {
49	        "<html><body><h1>Authentication successful!</h1><p>You can close this tab and return to the terminal.</p></body></html>"
50	    } else {
51	        "<html><body><h1>Authentication failed.</h1><p>Please try again.</p></body></html>"
52	    };
53	
54	    let response = format!(
55	        "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
56	        response_body.len(),
57	        response_body
58	    );
59	
60	    let mut writer = stream.try_clone()?;
61	    writer.write_all(response.as_bytes())?;
62	    writer.flush()?;
63	
64	    let code = code.ok_or_else(|| anyhow::anyhow!("no authorization code received"))?;
65	
66	    println!("Authorization code received. Exchanging for token...");
67	
68	    let token = exchange_code(auth_url, &code, &redirect_uri)?;
69	    save_token(&token)?;
70	
71	    println!("Logged in as {} (tenant: {})", token.email, token.tenant_id);
72	    Ok(())
73	}
