77	        Ok(token) => {
78	            let expired = token.expires_at < chrono::Utc::now().timestamp();
79	            println!("Logged in as: {}", token.email);
80	            println!("Tenant:       {}", token.tenant_id);
81	            println!("Expires:      {}", chrono::DateTime::from_timestamp(token.expires_at, 0)
82	                .map(|d| d.format("%Y-%m-%d %H:%M UTC").to_string())
83	                .unwrap_or_else(|| "unknown".to_string()));
84	            if expired {
85	                println!("Status:       EXPIRED (run `codeflow login` to refresh)");
86	            } else {
87	                println!("Status:       active");
88	            }
89	        }
90	        Err(_) => {
91	            println!("Not logged in. Run `codeflow login` to authenticate.");
92	        }
93	    }
94	    Ok(())
95	}
